<template>
  <div><PageHeader eyebrow="ASSESSMENT" title="Ngân hàng câu hỏi" description="Câu hỏi được version hóa; activity đã publish không thay đổi khi ngân hàng được cập nhật."><template #actions><button class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Tạo câu hỏi' }}</button></template></PageHeader><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><section v-if="showForm" class="panel" style="margin-bottom:16px"><form class="grid-two" @submit.prevent="create"><div class="form-field"><label>Topic</label><input v-model.trim="form.topic" class="form-input" required /></div><div class="form-field"><label>Độ khó</label><select v-model="form.difficulty" class="form-select"><option value="Easy">Dễ</option><option value="Medium">Trung bình</option><option value="Hard">Khó</option></select></div><div class="form-field"><label>Loại câu hỏi</label><select v-model="form.type" class="form-select"><option value="SingleChoice">Một lựa chọn</option><option value="MultipleChoice">Nhiều lựa chọn</option><option value="TrueFalse">Đúng / Sai</option><option value="ShortText">Trả lời ngắn</option><option value="LongText">Tự luận</option></select></div><div class="form-field"><label>Prompt</label><textarea v-model.trim="form.prompt" class="form-textarea" required></textarea></div><div class="form-field"><label>Options (A: Nội dung, mỗi dòng một lựa chọn)</label><textarea v-model="form.options" class="form-textarea" placeholder="A: Lựa chọn A\nB: Lựa chọn B"></textarea></div><div class="form-field"><label>Đáp án đúng (phân tách dấu phẩy)</label><input v-model.trim="form.correctAnswers" class="form-input" placeholder="A" /></div><button class="button primary" :disabled="busy">Tạo và version 1</button></form></section><section class="panel"><div class="toolbar"><input v-model="query" class="search-input" placeholder="Tìm theo topic…" /><span class="cell-subtle">{{ filtered.length }} câu hỏi</span></div><div v-if="loading" class="loading-state">Đang tải ngân hàng câu hỏi…</div><div v-else-if="filtered.length" class="list-compact"><div v-for="item in filtered" :key="item.id" class="list-compact-item"><div><strong>{{ item.topic }}</strong><span>Version {{ item.currentVersion }} · {{ item.difficulty || 'Chưa phân loại' }} · {{ item.id.slice(0, 8) }}</span></div><div class="card-actions"><StatusPill :value="item.status" /><button class="mini-button" @click="selectItem(item.id)">Quản lý version</button></div></div></div><div v-else class="empty-state"><strong>Chưa có câu hỏi</strong><span>Tạo câu hỏi với đáp án xác định để dùng lại trong activity.</span></div></section><section v-if="selected" class="panel" style="margin-top:16px"><div class="panel-heading"><div><h2>{{ selected.item.topic }}</h2><span>{{ selected.versions.length }} version</span></div><button class="mini-button" @click="selected = null">Đóng</button></div><div class="list-compact"><div v-for="version in selected.versions" :key="version.id" class="list-compact-item"><div><strong>v{{ version.version }} · {{ version.prompt }}</strong><span>{{ enumLabel(version.type) }} · {{ version.options.length }} lựa chọn</span></div><StatusPill :value="version.version === selected.item.currentVersion ? 'Current' : 'Immutable'" /></div></div><form class="stack" style="margin-top:14px" @submit.prevent="createVersion"><div class="form-field"><label>Prompt version mới</label><textarea v-model.trim="versionForm.prompt" class="form-textarea" required></textarea></div><div class="form-field"><label>Loại</label><select v-model="versionForm.type" class="form-select"><option value="SingleChoice">Một lựa chọn</option><option value="MultipleChoice">Nhiều lựa chọn</option><option value="TrueFalse">Đúng / Sai</option><option value="ShortText">Trả lời ngắn</option><option value="LongText">Tự luận</option></select></div><div class="form-field"><label>Options</label><textarea v-model="versionForm.options" class="form-textarea" placeholder="A: Lựa chọn A"></textarea></div><div class="form-field"><label>Đáp án đúng</label><input v-model.trim="versionForm.correctAnswers" class="form-input" placeholder="A" /></div><button class="button secondary" :disabled="busy">Tạo version {{ selected.item.currentVersion + 1 }}</button></form></section></div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import PageHeader from '../../../shared/ui/PageHeader.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import { assessmentApi } from '../../../shared/api/client'; import { enumLabel, type QuestionBankDetail, type QuestionBankItem } from '../../../shared/types'
const items = ref<QuestionBankItem[]>([]); const selected = ref<QuestionBankDetail | null>(null); const query = ref(''); const loading = ref(true); const busy = ref(false); const error = ref(''); const showForm = ref(false); const form = reactive({ topic: '', difficulty: 'Medium', type: 'MultipleChoice', prompt: '', options: '', correctAnswers: '' }); const versionForm = reactive({ prompt: '', type: 'MultipleChoice', options: '', correctAnswers: '' }); const filtered = computed(() => items.value.filter(item => `${item.topic} ${item.difficulty || ''}`.toLowerCase().includes(query.value.toLowerCase())))
function parseOptions(value: string) { return value.split('\n').map(line => { const [key, ...text] = line.split(':'); return { key: key.trim(), text: text.join(':').trim() } }).filter(item => item.key && item.text) }
function parseAnswers(value: string) { return value.split(',').map(item => item.trim()).filter(Boolean) }
async function load() { loading.value = true; try { items.value = await assessmentApi.questionBank() } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được ngân hàng câu hỏi.') } finally { loading.value = false } }
async function selectItem(id: string) { try { selected.value = await assessmentApi.questionBankDetail(id) } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được các version câu hỏi.') } }
async function create() { busy.value = true; try { const created = await assessmentApi.createQuestionBankItem({ topic: form.topic, difficulty: form.difficulty, type: form.type, prompt: form.prompt, options: parseOptions(form.options), correctAnswers: parseAnswers(form.correctAnswers) }); items.value.unshift(created.item); selected.value = created; showForm.value = false; form.topic = ''; form.prompt = ''; form.options = ''; form.correctAnswers = '' } catch (cause) { error.value = String((cause as Error)?.message || 'Không tạo được câu hỏi.') } finally { busy.value = false } }
async function createVersion() { if (!selected.value) return; busy.value = true; try { const version = await assessmentApi.createQuestionVersion(selected.value.item.id, { prompt: versionForm.prompt, type: versionForm.type, options: parseOptions(versionForm.options), correctAnswers: parseAnswers(versionForm.correctAnswers) }); selected.value.versions.unshift(version); selected.value.item.currentVersion = version.version; versionForm.prompt = ''; versionForm.options = ''; versionForm.correctAnswers = '' } catch (cause) { error.value = String((cause as Error)?.message || 'Không tạo được version mới.') } finally { busy.value = false } }
onMounted(load)
</script>
